 ext=[{'name':NAMES.get(k,k),'card_id':'mulanhua_'+k,'role':'主角' if k in ['mu_lanhua','mu_xiuzhen','gao_xiang'] else '重要配角','basis':'本书实际出场；系列综合经历另见主卡。'} for k in cast if not any(c['id']=='mulanhua_'+k for c in chars)]
